555-timer-calculator/calc.mjs.text:
// Pure calculation logic for the 555 timer calculator. No DOM, no network,
// no state — every function takes its inputs and returns a plain value, so
// it can be unit tested directly and reused unchanged from the browser UI.
//
// The datasheet formulas are only half the job. A 555 design that satisfies
// them can still be unbuildable: a standard astable cannot reach a duty
// cycle of 50% or below, R1 sets the peak current the discharge pin has to
// sink, and a bipolar NE555's timing drifts once the resistors get large
// enough that pin leakage competes with the charging current. The warnings
// this module emits are the part a bare `f = 1.44 / ((R1 + 2·R2)·C)`
// calculator leaves the user to discover on the bench.

const LN2 = Math.LN2; // 0.6931… — the charge/discharge constant of a 555's 1/3–2/3 Vcc window
const LN3 = Math.log(3); // 1.0986… — the monostable's 0 → 2/3 Vcc charge

// The 24 base values of the E24 preferred-number series (IEC 60063) — the
// resistors a hobbyist can actually buy, as opposed to the exact value the
// arithmetic asks for.
export const E24_BASE = [
  1.0, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2.0, 2.2, 2.4, 2.7, 3.0, 3.3, 3.6, 3.9,
  4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1,
];

// Practical bounds for a bipolar NE555, from its datasheet's application
// notes rather than from the timing equations, which have no opinion.
export const MIN_R1_OHMS = 1000; // below this the discharge transistor sinks too much current
export const MAX_TIMING_R_OHMS = 1e6; // above this, pin leakage starts to compete with the charging current
export const MAX_DISCHARGE_CURRENT_AMPS = 0.2; // absolute sink limit of the discharge pin

/** Rounds to 9 significant decimal places to suppress binary float noise. */
function clean(n) {
  return Number.parseFloat(n.toPrecision(9));
}

// Display precision is a separate decision from computational precision. The
// resistors this tool recommends are ±5% and a microfarad-scale timing cap can
// be −20%/+80%, so printing "1.02318797 kHz" would claim an accuracy the parts
// cannot deliver. Four significant figures is enough to pick components and
// honest about the rest; the returned numbers stay full precision.
function display(n) {
  return Number.parseFloat(n.toPrecision(4));
}

function requirePositive(value, label) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${label} must be a positive number.`);
  }
}

/** Finds the closest standard E24 resistor value to an arbitrary resistance. */
export function nearestStandardResistor(ohms) {
  requirePositive(ohms, "Resistance");
  const exponent = Math.floor(Math.log10(ohms));
  let best = null;
  // Check the decade above and below too: the closest E24 value to 9.6 Ω is
  // 10 Ω, which lives in the next decade up (1.0 × 10^1).
  for (const exp of [exponent - 1, exponent, exponent + 1]) {
    const scale = 10 ** exp;
    for (const base of E24_BASE) {
      const candidate = clean(base * scale);
      const diff = Math.abs(candidate - ohms);
      if (best === null || diff < best.diff) best = { value: candidate, diff };
    }
  }
  return best.value;
}

/** Formats an ohms value with the conventional Ω / kΩ / MΩ prefix. */
export function formatResistance(ohms) {
  if (!Number.isFinite(ohms) || ohms < 0) return "—";
  if (ohms >= 1e6) return `${display(ohms / 1e6)} MΩ`;
  if (ohms >= 1e3) return `${display(ohms / 1e3)} kΩ`;
  return `${display(ohms)} Ω`;
}

/** Formats a capacitance in farads with the prefix an engineer would write. */
export function formatCapacitance(farads) {
  if (!Number.isFinite(farads) || farads <= 0) return "—";
  if (farads >= 1e-3) return `${display(farads * 1e3)} mF`;
  if (farads >= 1e-6) return `${display(farads * 1e6)} µF`;
  if (farads >= 1e-9) return `${display(farads * 1e9)} nF`;
  return `${display(farads * 1e12)} pF`;
}

/** Formats a duration in seconds with a sensible s / ms / µs prefix. */
export function formatTime(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return "—";
  if (seconds >= 1) return `${display(seconds)} s`;
  if (seconds >= 1e-3) return `${display(seconds * 1e3)} ms`;
  if (seconds >= 1e-6) return `${display(seconds * 1e6)} µs`;
  return `${display(seconds * 1e9)} ns`;
}

/** Formats a frequency in hertz with a sensible Hz / kHz / MHz prefix. */
export function formatFrequency(hertz) {
  if (!Number.isFinite(hertz) || hertz <= 0) return "—";
  if (hertz >= 1e6) return `${display(hertz / 1e6)} MHz`;
  if (hertz >= 1e3) return `${display(hertz / 1e3)} kHz`;
  return `${display(hertz)} Hz`;
}

/**
 * Collects the buildability problems a set of astable component values has,
 * as {severity, message} objects. Severity "error" means the circuit will
 * misbehave or damage the chip; "warning" means it will run but the timing
 * won't match the arithmetic as closely as the numbers imply.
 */
function astableWarnings({ r1, r2, capacitanceFarads, supplyVolts }) {
  const notes = [];

  if (r1 < MIN_R1_OHMS) {
    notes.push({
      severity: "error",
      message:
        `R1 = ${formatResistance(r1)} is below the ${formatResistance(MIN_R1_OHMS)} practical minimum. ` +
        "During the discharge phase R1 is the only thing limiting current into the discharge pin, " +
        "so a small R1 can exceed the pin's sink rating and cook the chip.",
    });
  }

  const totalTimingR = r1 + r2;
  if (totalTimingR > MAX_TIMING_R_OHMS) {
    notes.push({
      severity: "warning",
      message:
        `R1 + R2 = ${formatResistance(totalTimingR)} exceeds the ${formatResistance(MAX_TIMING_R_OHMS)} ` +
        "rule of thumb for a bipolar NE555. At these values the threshold pin's own leakage current is " +
        "no longer negligible next to the charging current, so the real period drifts from the calculated " +
        "one and with temperature. A CMOS 555 (7555/TLC555) tolerates far higher resistances.",
    });
  }

  if (supplyVolts !== undefined && supplyVolts !== null) {
    // The discharge transistor saturates at roughly 0.1–0.3 V, so at the
    // instant discharge begins it pulls pin 7 to ~0 V. Two currents converge
    // on that pin from there: the full supply across R1 (Vcc to pin 7), and
    // the timing cap's charge — at its peak, 2/3 Vcc — draining back through
    // R2 (pin 7 sits between R1 and R2 in the standard astable topology).
    // An earlier version of this formula charged the cap's 2/3 Vcc through R1
    // instead of the full supply, and dropped the R2 term outright — both
    // errors made small, understating the true pin current and occasionally
    // missing this warning entirely for a component pair that overloads the
    // pin (e.g. R1 = 1 kΩ, R2 = 50 Ω, 15 V: reports 10 mA, actually 215 mA).
    const dischargePeakAmps = supplyVolts / r1 + ((2 / 3) * supplyVolts) / r2;
    if (dischargePeakAmps > MAX_DISCHARGE_CURRENT_AMPS) {
      notes.push({
        severity: "error",
        message:
          `At the instant discharge starts, the discharge pin sinks about ${display(dischargePeakAmps * 1000)} mA ` +
          `from R1 and R2 combined — above its ${MAX_DISCHARGE_CURRENT_AMPS * 1000} mA limit. Raise R1, raise R2, ` +
          "or lower the supply.",
      });
    }
  }

  if (capacitanceFarads >= 1e-6) {
    notes.push({
      severity: "warning",
      message:
        `A timing capacitor of ${formatCapacitance(capacitanceFarads)} is almost certainly an electrolytic, ` +
        "whose tolerance is commonly −20%/+80% and which drifts with age and temperature. Treat the " +
        "frequency below as a target, not a specification, and trim with R2 if it matters.",
    });
  }

  return notes;
}

/**
 * Analyses a standard two-resistor 555 astable (the textbook oscillator):
 * the capacitor charges through R1 + R2 and discharges through R2 alone,
 * which is exactly why its duty cycle can never reach 50%.
 *
 * `supplyVolts` is optional and only used for the discharge-current check.
 */
export function calculateAstable({ r1, r2, capacitanceFarads, supplyVolts }) {
  requirePositive(r1, "R1");
  requirePositive(r2, "R2");
  requirePositive(capacitanceFarads, "Capacitance");
  if (supplyVolts !== undefined && supplyVolts !== null) {
    requirePositive(supplyVolts, "Supply voltage");
  }

  const highSeconds = LN2 * (r1 + r2) * capacitanceFarads;
  const lowSeconds = LN2 * r2 * capacitanceFarads;
  const periodSeconds = highSeconds + lowSeconds;

  return {
    highSeconds: clean(highSeconds),
    lowSeconds: clean(lowSeconds),
    periodSeconds: clean(periodSeconds),
    frequencyHz: clean(1 / periodSeconds),
    dutyCyclePercent: clean((highSeconds / periodSeconds) * 100),
    notes: astableWarnings({ r1, r2, capacitanceFarads, supplyVolts }),
  };
}

/**
 * Solves the astable backwards: given the frequency and duty cycle you want
 * and the capacitor you have, returns the exact R1/R2 and the nearest E24
 * pair you can actually buy, plus what that buyable pair really produces.
 *
 * Derivation, so the constants aren't magic: with
 * K = 1 / (ln2 · f · C) = R1 + 2·R2 and D = (R1 + R2) / (R1 + 2·R2),
 * the two equations collapse to R1 = K·(2D − 1) and R2 = K·(1 − D).
 * R1 → 0 as D → 0.5, which is the algebraic form of "a standard astable
 * can't do 50% or below".
 */
export function designAstable({ frequencyHz, dutyCyclePercent, capacitanceFarads, supplyVolts }) {
  requirePositive(frequencyHz, "Frequency");
  requirePositive(capacitanceFarads, "Capacitance");
  if (!Number.isFinite(dutyCyclePercent)) {
    throw new Error("Duty cycle must be a number.");
  }
  if (dutyCyclePercent <= 50 || dutyCyclePercent >= 100) {
    throw new Error(
      `A standard two-resistor 555 astable can only produce a duty cycle above 50% and below 100% — ` +
        `${clean(dutyCyclePercent)}% is outside that range. The output is high while the capacitor charges ` +
        "through R1 + R2 and low while it discharges through R2 alone, so the high time is always the " +
        "longer of the two. For 50% or less, add a diode across R2 so charging bypasses it, or use a " +
        "CMOS 555 in a 50%-duty configuration.",
    );
  }

  const duty = dutyCyclePercent / 100;
  const k = 1 / (LN2 * frequencyHz * capacitanceFarads);
  const exactR1 = k * (2 * duty - 1);
  const exactR2 = k * (1 - duty);

  const nearestR1 = nearestStandardResistor(exactR1);
  const nearestR2 = nearestStandardResistor(exactR2);
  const achieved = calculateAstable({
    r1: nearestR1,
    r2: nearestR2,
    capacitanceFarads,
    supplyVolts,
  });

  return {
    exactR1: clean(exactR1),
    exactR2: clean(exactR2),
    nearestR1,
    nearestR2,
    achievedFrequencyHz: achieved.frequencyHz,
    achievedDutyCyclePercent: achieved.dutyCyclePercent,
    frequencyErrorPercent: clean(((achieved.frequencyHz - frequencyHz) / frequencyHz) * 100),
    dutyErrorPercent: clean(achieved.dutyCyclePercent - dutyCyclePercent),
    notes: achieved.notes,
  };
}

/**
 * Designs the diode-mod astable: a diode in parallel with R2, forward-biased
 * so it shorts R2 out of the charge path. The capacitor then charges through
 * R1 alone and discharges through R2 alone, so high time and low time no
 * longer share a resistor — duty = R1 / (R1 + R2), free to go below 50%,
 * unlike the plain two-resistor astable `designAstable` rejects for exactly
 * that range.
 *
 * The diode's own forward voltage drop (~0.5–0.7 V for silicon, lower for
 * Schottky) is not in this formula — it is a real error source this function
 * cannot correct without knowing which diode, so it is surfaced as a warning
 * instead of folded into the arithmetic as false precision.
 */
export function designAstableWithDiode({ frequencyHz, dutyCyclePercent, capacitanceFarads, supplyVolts }) {
  requirePositive(frequencyHz, "Frequency");
  requirePositive(capacitanceFarads, "Capacitance");
  if (!Number.isFinite(dutyCyclePercent)) {
    throw new Error("Duty cycle must be a number.");
  }
  if (dutyCyclePercent <= 0 || dutyCyclePercent >= 100) {
    throw new Error(
      `Duty cycle must be between 0% and 100% (exclusive) — ${clean(dutyCyclePercent)}% is outside that range.`,
    );
  }

  const duty = dutyCyclePercent / 100;
  const sumR = 1 / (LN2 * frequencyHz * capacitanceFarads);
  const exactR1 = sumR * duty;
  const exactR2 = sumR * (1 - duty);

  const nearestR1 = nearestStandardResistor(exactR1);
  const nearestR2 = nearestStandardResistor(exactR2);

  const highSeconds = LN2 * nearestR1 * capacitanceFarads;
  const lowSeconds = LN2 * nearestR2 * capacitanceFarads;
  const periodSeconds = highSeconds + lowSeconds;
  const achievedFrequencyHz = clean(1 / periodSeconds);
  const achievedDutyCyclePercent = clean((highSeconds / periodSeconds) * 100);

  // Buildability warnings mirror `astableWarnings`, but the diode changes
  // which physical path each resistor sits on, so they are recomputed here
  // rather than reused: charge now runs through R1 alone (the diode bypasses
  // R2), and discharge still runs through R2 alone, same as the plain
  // astable, so the discharge-current model (R1 from Vcc, R2 from the cap's
  // 2/3-Vcc peak) is unchanged and still applies.
  const notes = [];
  if (nearestR1 < MIN_R1_OHMS) {
    notes.push({
      severity: "error",
      message:
        `R1 = ${formatResistance(nearestR1)} is below the ${formatResistance(MIN_R1_OHMS)} practical minimum.`,
    });
  }
  const totalTimingR = nearestR1 + nearestR2;
  if (totalTimingR > MAX_TIMING_R_OHMS) {
    notes.push({
      severity: "warning",
      message:
        `R1 + R2 = ${formatResistance(totalTimingR)} exceeds the ${formatResistance(MAX_TIMING_R_OHMS)} ` +
        "rule of thumb for a bipolar NE555 — pin leakage will make the real timing drift from this " +
        "calculation. A CMOS 555 (7555/TLC555) tolerates far higher resistances.",
    });
  }
  if (supplyVolts !== undefined && supplyVolts !== null) {
    requirePositive(supplyVolts, "Supply voltage");
    const dischargePeakAmps = supplyVolts / nearestR1 + ((2 / 3) * supplyVolts) / nearestR2;
    if (dischargePeakAmps > MAX_DISCHARGE_CURRENT_AMPS) {
      notes.push({
        severity: "error",
        message:
          `At the instant discharge starts, the discharge pin sinks about ${display(dischargePeakAmps * 1000)} mA ` +
          `from R1 and R2 combined — above its ${MAX_DISCHARGE_CURRENT_AMPS * 1000} mA limit. Raise R1, raise R2, ` +
          "or lower the supply.",
      });
    }
  }
  notes.push({
    severity: "warning",
    message:
      "This formula treats the diode as ideal. A real silicon diode drops roughly 0.5–0.7 V (a Schottky " +
      "less) while it conducts, which shortens the charge time slightly and pulls the achieved duty cycle " +
      "down from the number below — more noticeably at low supply voltages or low R1, where that drop is a " +
      "larger fraction of the charging voltage. Bench-trim R1 if the exact duty cycle matters.",
  });
  if (capacitanceFarads >= 1e-6) {
    notes.push({
      severity: "warning",
      message:
        `A timing capacitor of ${formatCapacitance(capacitanceFarads)} is almost certainly an electrolytic, ` +
        "whose tolerance is commonly −20%/+80% and which drifts with age and temperature.",
    });
  }

  return {
    exactR1: clean(exactR1),
    exactR2: clean(exactR2),
    nearestR1,
    nearestR2,
    achievedFrequencyHz,
    achievedDutyCyclePercent,
    frequencyErrorPercent: clean(((achievedFrequencyHz - frequencyHz) / frequencyHz) * 100),
    dutyErrorPercent: clean(achievedDutyCyclePercent - dutyCyclePercent),
    notes,
  };
}

/**
 * Analyses a 555 monostable (one-shot): a trigger pulse starts a single
 * output pulse of ln(3)·R·C, after which the output returns low regardless
 * of the input.
 */
export function calculateMonostable({ r, capacitanceFarads, supplyVolts }) {
  requirePositive(r, "R");
  requirePositive(capacitanceFarads, "Capacitance");
  if (supplyVolts !== undefined && supplyVolts !== null) {
    requirePositive(supplyVolts, "Supply voltage");
  }

  const notes = [];
  if (r < MIN_R1_OHMS) {
    notes.push({
      severity: "error",
      message:
        `R = ${formatResistance(r)} is below the ${formatResistance(MIN_R1_OHMS)} practical minimum. ` +
        "R also limits the current the discharge pin sinks when the pulse ends.",
    });
  }
  if (r > MAX_TIMING_R_OHMS) {
    notes.push({
      severity: "warning",
      message:
        `R = ${formatResistance(r)} exceeds the ${formatResistance(MAX_TIMING_R_OHMS)} rule of thumb for a ` +
        "bipolar NE555; leakage at the threshold pin makes the real pulse width drift. A CMOS 555 " +
        "(7555/TLC555) handles far higher resistances.",
    });
  }
  if (capacitanceFarads >= 1e-6) {
    notes.push({
      severity: "warning",
      message:
        `A timing capacitor of ${formatCapacitance(capacitanceFarads)} is almost certainly an electrolytic ` +
        "(−20%/+80% is a common tolerance), so the real pulse width will vary noticeably from the number below.",
    });
  }
  notes.push({
    severity: "info",
    message:
      "The trigger pulse must be shorter than the output pulse, and the trigger pin must be held above " +
      "1/3 Vcc between triggers — otherwise the 555 re-triggers and the output never falls.",
  });

  return {
    pulseSeconds: clean(LN3 * r * capacitanceFarads),
    notes,
  };
}

/**
 * Solves the monostable backwards: given the pulse width you want and the
 * capacitor you have, returns the exact R, the nearest E24 R, and the pulse
 * that buyable resistor actually produces.
 */
export function designMonostable({ pulseSeconds, capacitanceFarads, supplyVolts }) {
  requirePositive(pulseSeconds, "Pulse width");
  requirePositive(capacitanceFarads, "Capacitance");

  const exactR = pulseSeconds / (LN3 * capacitanceFarads);
  const nearestR = nearestStandardResistor(exactR);
  const achieved = calculateMonostable({ r: nearestR, capacitanceFarads, supplyVolts });

  return {
    exactR: clean(exactR),
    nearestR,
    achievedPulseSeconds: achieved.pulseSeconds,
    pulseErrorPercent: clean(((achieved.pulseSeconds - pulseSeconds) / pulseSeconds) * 100),
    notes: achieved.notes,
  };
}

555-timer-calculator/usage.mjs.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No IDs, no IPs, no content — just an event
// name and a day, kept in this browser's own localStorage. Nothing is sent
// anywhere; there is no server for it to go to. Off-switchable, and honors
// Do Not Track / Global Privacy Control automatically.

const STORAGE_KEY = "555-timer-calculator:usage-events";
const OPT_OUT_KEY = "555-timer-calculator:usage-opt-out";

function hasStorage() {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function honorsBrowserSignal() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function isUsageCountingEnabled() {
  if (!hasStorage()) return false;
  if (honorsBrowserSignal()) return false;
  try {
    return localStorage.getItem(OPT_OUT_KEY) !== "1";
  } catch {
    return false;
  }
}

export function setUsageCountingEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch {
    // storage unavailable (private mode, quota) — nothing to do
  }
}

/** Records that `eventName` happened today. Aggregate count only; no payload beyond the event name and the day. */
export function recordEvent(eventName) {
  if (!isUsageCountingEnabled()) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const raw = localStorage.getItem(STORAGE_KEY);
    const events = raw ? JSON.parse(raw) : {};
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch {
    // storage unavailable — counting is best-effort only
  }
}

// How long an input must sit unchanged before the interaction counts as one
// event. Long enough to span ordinary typing (including a pause to look at
// the result), short enough that a user who types and immediately leaves is
// still counted.
const SETTLE_MS = 800;

const pendingTimers = new Map();

/**
 * Records `eventName` once the user has stopped changing inputs, rather than
 * once per keystroke.
 *
 * These tools recompute on every `input` event, which is right for the
 * result but wrong for the counter: calling recordEvent() from that handler
 * counted keystrokes, so typing "220" into one field recorded three
 * calculations and a five-field form could record a dozen. That made the
 * only signal these tools produce -- "did anyone actually use this" --
 * unreadable, and portfolio/usage/ is what decides what gets built next.
 *
 * Repeated calls for the same event name collapse into one, so a burst of
 * typing yields a single count once it settles. Different event names are
 * tracked independently, so two calculators on one page each keep their own.
 */
export function recordEventSettled(eventName, delayMs = SETTLE_MS) {
  const existing = pendingTimers.get(eventName);
  if (existing !== undefined) clearTimeout(existing);
  const timer = setTimeout(() => {
    pendingTimers.delete(eventName);
    recordEvent(eventName);
  }, delayMs);
  // Under Node (the test runner) a pending timer keeps the process alive;
  // browsers have no unref, hence the guard rather than a bare call.
  if (typeof timer === "object" && typeof timer?.unref === "function") timer.unref();
  pendingTimers.set(eventName, timer);
}

/** Records any settled-but-not-yet-written events immediately. Exists so tests need not wait on wall-clock time. */
export function flushSettledEvents() {
  for (const [eventName, timer] of pendingTimers) {
    clearTimeout(timer);
    recordEvent(eventName);
  }
  pendingTimers.clear();
}

/** Discards pending settled events without recording them. Used by tests to isolate cases. */
export function cancelSettledEvents() {
  for (const timer of pendingTimers.values()) clearTimeout(timer);
  pendingTimers.clear();
}

/** Returns the raw local event counts, for the user's own inspection. */
export function readLocalUsage() {
  if (!hasStorage()) return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

led-resistor-calculator/calc.mjs.text:
// Pure calculation logic for the LED series-resistor calculator. No DOM, no
// network, no state — every function takes its inputs and returns a plain
// value, so it can be unit tested directly and reused unchanged from the
// browser UI.

/** Formats an ohms value with the conventional Ω / kΩ / MΩ prefix. */
export function formatResistance(ohms) {
  if (!Number.isFinite(ohms) || ohms < 0) return "—";
  const units = [
    [1e6, "MΩ"],
    [1e3, "kΩ"],
    [1, "Ω"],
  ];
  for (const [scale, suffix] of units) {
    if (ohms >= scale) {
      const value = ohms / scale;
      const rounded = Math.round(value * 1000) / 1000;
      return `${rounded} ${suffix}`;
    }
  }
  return `${Math.round(ohms * 1000) / 1000} Ω`;
}

// The 24 base values of the E24 preferred-number series (IEC 60063), used
// for both resistance decades and read off as the resistors a hobbyist can
// actually buy.
export const E24_BASE = [
  1.0, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2.0, 2.2, 2.4, 2.7, 3.0, 3.3, 3.6, 3.9,
  4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1,
];

/** Rounds to 6 significant decimal places to suppress binary float noise. */
function clean(n) {
  return Math.round(n * 1e6) / 1e6;
}

/** Finds the closest standard E24 resistor value to an arbitrary resistance. */
export function nearestStandardResistor(ohms) {
  if (!Number.isFinite(ohms) || ohms <= 0) {
    throw new Error("Resistance must be a positive finite number.");
  }
  const exponent = Math.floor(Math.log10(ohms));
  let best = null;
  // Check the decade above and below too: the closest E24 value to, say,
  // 9.6 Ω is 10 Ω, which lives in the next decade up (1.0 * 10^1).
  for (const exp of [exponent - 1, exponent, exponent + 1]) {
    const scale = 10 ** exp;
    for (const base of E24_BASE) {
      const candidate = clean(base * scale);
      const diff = Math.abs(candidate - ohms);
      if (best === null || diff < best.diff) best = { value: candidate, diff };
    }
  }
  return best.value;
}

// Common off-the-shelf through-hole resistor power ratings, ascending.
export const STANDARD_POWER_RATINGS_WATTS = [0.0625, 0.125, 0.25, 0.5, 1, 2, 3, 5];

/**
 * Picks the smallest standard power rating that covers the computed
 * dissipation with a safety margin (derating a resistor to roughly half its
 * rated power is standard practice for reliability and longevity).
 * Returns null if the load exceeds common through-hole ratings.
 */
export function recommendedPowerRating(watts, safetyFactor = 2) {
  if (!Number.isFinite(watts) || watts < 0) {
    throw new Error("Power must be a non-negative number.");
  }
  const target = watts * safetyFactor;
  for (const rating of STANDARD_POWER_RATINGS_WATTS) {
    if (rating >= target) return rating;
  }
  return null;
}

/**
 * Computes the current-limiting series resistor for one or more LEDs in
 * series driven from a fixed supply, plus the nearest resistor value you can
 * actually buy and what that does to the current and dissipation.
 */
export function calculateLedResistor({
  supplyVoltage,
  ledForwardVoltage,
  ledForwardCurrentMa,
  numLeds = 1,
}) {
  if (!Number.isFinite(supplyVoltage) || supplyVoltage <= 0) {
    throw new Error("Supply voltage must be a positive number.");
  }
  if (!Number.isFinite(ledForwardVoltage) || ledForwardVoltage <= 0) {
    throw new Error("LED forward voltage must be a positive number.");
  }
  if (!Number.isFinite(ledForwardCurrentMa) || ledForwardCurrentMa <= 0) {
    throw new Error("LED forward current must be a positive number.");
  }
  if (!Number.isInteger(numLeds) || numLeds < 1) {
    throw new Error("Number of LEDs in series must be a positive whole number.");
  }

  const totalLedVoltage = clean(ledForwardVoltage * numLeds);
  if (totalLedVoltage >= supplyVoltage) {
    throw new Error(
      `Supply voltage (${supplyVoltage} V) must exceed the total LED forward voltage ` +
        `(${totalLedVoltage} V for ${numLeds} LED${numLeds > 1 ? "s" : ""} in series) — ` +
        "there is no headroom left for a current-limiting resistor.",
    );
  }

  const currentAmps = ledForwardCurrentMa / 1000;
  const headroomVoltage = supplyVoltage - totalLedVoltage;
  const requiredOhms = clean(headroomVoltage / currentAmps);
  const powerWatts = clean(currentAmps * currentAmps * requiredOhms);

  const nearestStandardOhms = nearestStandardResistor(requiredOhms);
  const currentAtNearestAmps = headroomVoltage / nearestStandardOhms;
  const currentAtNearestMa = clean(currentAtNearestAmps * 1000);
  const powerAtNearestWatts = clean(currentAtNearestAmps * currentAtNearestAmps * nearestStandardOhms);

  return {
    totalLedVoltage,
    requiredOhms,
    formattedRequired: formatResistance(requiredOhms),
    powerWatts,
    recommendedPowerRatingWatts: recommendedPowerRating(powerWatts),
    nearestStandardOhms,
    formattedNearestStandard: formatResistance(nearestStandardOhms),
    currentAtNearestMa,
    powerAtNearestWatts,
    recommendedPowerRatingAtNearestWatts: recommendedPowerRating(powerAtNearestWatts),
  };
}

led-resistor-calculator/usage.mjs.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No IDs, no IPs, no content — just an event
// name and a day, kept in this browser's own localStorage. Nothing is sent
// anywhere; there is no server for it to go to. Off-switchable, and honors
// Do Not Track / Global Privacy Control automatically.

const STORAGE_KEY = "led-resistor-calculator:usage-events";
const OPT_OUT_KEY = "led-resistor-calculator:usage-opt-out";

function hasStorage() {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function honorsBrowserSignal() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function isUsageCountingEnabled() {
  if (!hasStorage()) return false;
  if (honorsBrowserSignal()) return false;
  try {
    return localStorage.getItem(OPT_OUT_KEY) !== "1";
  } catch {
    return false;
  }
}

export function setUsageCountingEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch {
    // storage unavailable (private mode, quota) — nothing to do
  }
}

/** Records that `eventName` happened today. Aggregate count only; no payload beyond the event name and the day. */
export function recordEvent(eventName) {
  if (!isUsageCountingEnabled()) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const raw = localStorage.getItem(STORAGE_KEY);
    const events = raw ? JSON.parse(raw) : {};
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch {
    // storage unavailable — counting is best-effort only
  }
}

// How long an input must sit unchanged before the interaction counts as one
// event. Long enough to span ordinary typing (including a pause to look at
// the result), short enough that a user who types and immediately leaves is
// still counted.
const SETTLE_MS = 800;

const pendingTimers = new Map();

/**
 * Records `eventName` once the user has stopped changing inputs, rather than
 * once per keystroke.
 *
 * These tools recompute on every `input` event, which is right for the
 * result but wrong for the counter: calling recordEvent() from that handler
 * counted keystrokes, so typing "220" into one field recorded three
 * calculations and a five-field form could record a dozen. That made the
 * only signal these tools produce -- "did anyone actually use this" --
 * unreadable, and portfolio/usage/ is what decides what gets built next.
 *
 * Repeated calls for the same event name collapse into one, so a burst of
 * typing yields a single count once it settles. Different event names are
 * tracked independently, so two calculators on one page each keep their own.
 */
export function recordEventSettled(eventName, delayMs = SETTLE_MS) {
  const existing = pendingTimers.get(eventName);
  if (existing !== undefined) clearTimeout(existing);
  const timer = setTimeout(() => {
    pendingTimers.delete(eventName);
    recordEvent(eventName);
  }, delayMs);
  // Under Node (the test runner) a pending timer keeps the process alive;
  // browsers have no unref, hence the guard rather than a bare call.
  if (typeof timer === "object" && typeof timer?.unref === "function") timer.unref();
  pendingTimers.set(eventName, timer);
}

/** Records any settled-but-not-yet-written events immediately. Exists so tests need not wait on wall-clock time. */
export function flushSettledEvents() {
  for (const [eventName, timer] of pendingTimers) {
    clearTimeout(timer);
    recordEvent(eventName);
  }
  pendingTimers.clear();
}

/** Discards pending settled events without recording them. Used by tests to isolate cases. */
export function cancelSettledEvents() {
  for (const timer of pendingTimers.values()) clearTimeout(timer);
  pendingTimers.clear();
}

/** Returns the raw local event counts, for the user's own inspection. */
export function readLocalUsage() {
  if (!hasStorage()) return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

led-resistor-calculator/wiring.mjs.text:
// Pure logic for "one resistor for all my LEDs, or one each?" — the wiring
// decision that comes immediately after the single-LED resistor value.
//
// No DOM, no network, no state. Same shape as calc.mjs so both can be unit
// tested directly and reused unchanged from the browser.
//
// Why this is a separate module rather than more of calc.mjs: calc.mjs sizes
// one resistor for one branch and is what the live calculator imports. This
// asks a different question — given N LEDs, which of three standard wirings
// should you build — and answers it by calling that same sizing function
// three times. Keeping them apart means this page cannot regress the tool it
// links back to.

import {
  formatResistance,
  nearestStandardResistor,
  recommendedPowerRating,
} from "./calc.mjs";

/** Rounds to 6 significant decimal places to suppress binary float noise. */
function clean(n) {
  return Math.round(n * 1e6) / 1e6;
}

/**
 * The most LEDs of this forward voltage that can sit in one series string on
 * this supply and still leave the resistor something to drop.
 *
 * `minHeadroomVolts` is why this is not simply `floor(supply / vf)`. A string
 * that consumes the entire supply leaves the resistor 0 V, which is not a
 * circuit — the current is then set by nothing but the LEDs' own bulk
 * resistance and the supply's tolerance, which is the failure this whole page
 * is about. A tenth of a volt is not a design margin; it is the smallest
 * headroom at which the arithmetic still describes a real resistor.
 */
export function maxLedsInSeries(supplyVoltage, ledForwardVoltage, minHeadroomVolts = 0.1) {
  if (!Number.isFinite(supplyVoltage) || supplyVoltage <= 0) {
    throw new Error("Supply voltage must be a positive number.");
  }
  if (!Number.isFinite(ledForwardVoltage) || ledForwardVoltage <= 0) {
    throw new Error("LED forward voltage must be a positive number.");
  }
  const usable = supplyVoltage - minHeadroomVolts;
  return Math.max(0, Math.floor(clean(usable / ledForwardVoltage)));
}

/** One wiring option, priced the same way for all three so they compare. */
function describeOption({
  key,
  label,
  resistorCount,
  resistorOhms,
  branchCurrentAmps,
  supplyCurrentAmps,
  supplyVoltage,
  ledPowerWatts,
}) {
  const perResistorWatts = clean(branchCurrentAmps * branchCurrentAmps * resistorOhms);
  const nearest = nearestStandardResistor(resistorOhms);
  const supplyPowerWatts = clean(supplyVoltage * supplyCurrentAmps);
  return {
    key,
    label,
    resistorCount,
    resistorOhms,
    formattedResistor: formatResistance(resistorOhms),
    nearestStandardOhms: nearest,
    formattedNearestStandard: formatResistance(nearest),
    perResistorWatts,
    recommendedPowerRatingWatts: recommendedPowerRating(perResistorWatts),
    supplyCurrentMa: clean(supplyCurrentAmps * 1000),
    supplyPowerWatts,
    ledPowerWatts: clean(ledPowerWatts),
    // Everything the supply delivers that does not end up as light is heat in
    // the resistors. Stated as its own figure because it is the number that
    // decides a battery-powered build.
    wastedPowerWatts: clean(supplyPowerWatts - ledPowerWatts),
    efficiencyPercent:
      supplyPowerWatts > 0 ? clean((ledPowerWatts / supplyPowerWatts) * 100) : 0,
  };
}

/**
 * Compares the three ways people actually wire N LEDs on one supply.
 *
 * 1. **Series string, one resistor.** Every LED carries the same current
 *    because it is literally the same current. Needs the supply to exceed the
 *    combined forward voltage.
 * 2. **Parallel branches, one resistor each.** Always available. Each
 *    branch's current is set by its own resistor, so a forward-voltage
 *    mismatch between LEDs changes brightness slightly and nothing else.
 * 3. **Parallel LEDs sharing one resistor.** One part, and the reason this
 *    page exists — see `sharedResistorRisk` on the returned option.
 */
export function compareLedWiring({
  supplyVoltage,
  ledForwardVoltage,
  ledForwardCurrentMa,
  numLeds,
}) {
  if (!Number.isFinite(supplyVoltage) || supplyVoltage <= 0) {
    throw new Error("Supply voltage must be a positive number.");
  }
  if (!Number.isFinite(ledForwardVoltage) || ledForwardVoltage <= 0) {
    throw new Error("LED forward voltage must be a positive number.");
  }
  if (!Number.isFinite(ledForwardCurrentMa) || ledForwardCurrentMa <= 0) {
    throw new Error("LED forward current must be a positive number.");
  }
  if (!Number.isInteger(numLeds) || numLeds < 1) {
    throw new Error("Number of LEDs must be a positive whole number.");
  }
  if (ledForwardVoltage >= supplyVoltage) {
    throw new Error(
      `Supply voltage (${supplyVoltage} V) must exceed one LED's forward voltage ` +
        `(${ledForwardVoltage} V) — no wiring works without headroom for a resistor.`,
    );
  }

  const branchCurrentAmps = ledForwardCurrentMa / 1000;
  const seriesLimit = maxLedsInSeries(supplyVoltage, ledForwardVoltage);
  const options = [];

  // ---- 1. Series string ---------------------------------------------------
  const totalSeriesVf = clean(ledForwardVoltage * numLeds);
  const seriesAvailable = numLeds <= seriesLimit;
  if (seriesAvailable) {
    const seriesOhms = clean((supplyVoltage - totalSeriesVf) / branchCurrentAmps);
    options.push({
      ...describeOption({
        key: "series",
        label: `All ${numLeds} in series, 1 resistor`,
        resistorCount: 1,
        resistorOhms: seriesOhms,
        branchCurrentAmps,
        // The whole string is one branch: the supply delivers the design
        // current once, not once per LED. This is the entire efficiency
        // argument for series and the reason it is the default answer.
        supplyCurrentAmps: branchCurrentAmps,
        supplyVoltage,
        ledPowerWatts: totalSeriesVf * branchCurrentAmps,
      }),
      available: true,
      totalForwardVoltage: totalSeriesVf,
    });
  } else {
    options.push({
      key: "series",
      label: `All ${numLeds} in series, 1 resistor`,
      available: false,
      totalForwardVoltage: totalSeriesVf,
      unavailableReason:
        `${numLeds} LEDs in series need ${clean(totalSeriesVf)} V before the resistor, ` +
        `which a ${supplyVoltage} V supply cannot provide. This supply fits ` +
        `${seriesLimit} in a string.`,
    });
  }

  // ---- 2. Parallel branches, one resistor each ---------------------------
  const individualOhms = clean((supplyVoltage - ledForwardVoltage) / branchCurrentAmps);
  options.push({
    ...describeOption({
      key: "individual",
      label: `${numLeds} in parallel, ${numLeds} resistor${numLeds > 1 ? "s" : ""}`,
      resistorCount: numLeds,
      resistorOhms: individualOhms,
      branchCurrentAmps,
      supplyCurrentAmps: branchCurrentAmps * numLeds,
      supplyVoltage,
      ledPowerWatts: ledForwardVoltage * branchCurrentAmps * numLeds,
    }),
    available: true,
  });

  // ---- 3. Parallel LEDs sharing one resistor -----------------------------
  //
  // The resistor is sized for the *total* current, which is the only quantity
  // it actually controls. How that total divides between the LEDs is set by
  // their forward-voltage curves, which no resistor in this position can
  // influence: they all sit across the same node.
  const sharedCurrentAmps = branchCurrentAmps * numLeds;
  const sharedOhms = clean((supplyVoltage - ledForwardVoltage) / sharedCurrentAmps);
  const sharedOption = describeOption({
    key: "shared",
    label: `${numLeds} in parallel, 1 shared resistor`,
    resistorCount: 1,
    resistorOhms: sharedOhms,
    branchCurrentAmps: sharedCurrentAmps,
    supplyCurrentAmps: sharedCurrentAmps,
    supplyVoltage,
    ledPowerWatts: ledForwardVoltage * branchCurrentAmps * numLeds,
  });
  options.push({
    ...sharedOption,
    available: true,
    // Deliberately a bound, not a prediction. Predicting the actual split
    // needs each LED's own forward-voltage curve, which is a per-part
    // measurement this page does not have and will not invent. What is
    // certain is the ceiling: the resistor fixes the total, so if the
    // lowest-forward-voltage LED ends up carrying it alone, it carries all
    // of it.
    sharedResistorRisk:
      numLeds > 1
        ? {
            designCurrentMa: clean(ledForwardCurrentMa),
            worstCaseCurrentMa: clean(ledForwardCurrentMa * numLeds),
            worstCaseMultiple: numLeds,
          }
        : null,
  });

  // Series where it fits, individual resistors where it does not. The shared
  // resistor is never recommended: it costs the same power as individual
  // resistors (both drop supply - Vf at the same total current) and buys
  // nothing but a lower part count, in exchange for giving up control of the
  // one quantity an LED's life depends on.
  const recommended = seriesAvailable && numLeds > 1 ? "series" : "individual";

  return {
    supplyVoltage,
    ledForwardVoltage,
    ledForwardCurrentMa,
    numLeds,
    maxLedsInSeries: seriesLimit,
    options,
    recommended,
  };
}

/** One plain sentence naming the choice and why, for the result panel. */
export function wiringNote(result) {
  const { recommended, numLeds, maxLedsInSeries: limit } = result;
  if (numLeds === 1) {
    return "One LED has only one wiring. The resistor value below is the whole answer.";
  }
  const series = result.options.find((o) => o.key === "series");
  const individual = result.options.find((o) => o.key === "individual");
  if (recommended === "series") {
    const saved = clean(individual.wastedPowerWatts - series.wastedPowerWatts);
    return (
      `Wire all ${numLeds} in series with one resistor. Every LED carries the same ` +
      `current because it is the same current, and the string wastes ` +
      `${saved.toFixed(3)} W less heat than ${numLeds} separate resistors.`
    );
  }
  return (
    `A ${numLeds}-LED series string needs more voltage than this supply has ` +
    `(it fits ${limit}). Give each LED its own resistor: one shared resistor ` +
    `costs exactly the same power and gives up control of the current.`
  );
}

rc-filter-calculator/calc.mjs.text:
// Pure calculation logic for the RC / RL filter cutoff-frequency calculator.
// No DOM, no network, no state — every function takes its inputs and returns
// a plain value, so it can be unit tested directly and reused unchanged from
// the browser UI.
//
// A first-order RC or RL filter has a single -3 dB cutoff frequency where the
// output power falls to half the input:
//
//   RC filter: f_c = 1 / (2·π·R·C),   time constant τ = R·C
//   RL filter: f_c = R / (2·π·L),     time constant τ = L / R
//
// Whether the filter is low-pass or high-pass depends only on where the
// output is taken (across C vs R, or across R vs L) — the cutoff frequency
// and time constant are identical either way, so the topology selection here
// only affects the explanatory labels, not the arithmetic.

/** Rounds a value to `sig` significant figures (for display of derived components). */
export function toSignificant(value, sig = 4) {
  if (!Number.isFinite(value) || value === 0) return value;
  const exponent = Math.floor(Math.log10(Math.abs(value)));
  const factor = 10 ** (sig - 1 - exponent);
  return Math.round(value * factor) / factor;
}

/** Formats a resistance in Ω / kΩ / MΩ. */
export function formatResistance(ohms) {
  return formatWithPrefix(ohms, [
    [1e6, "MΩ"],
    [1e3, "kΩ"],
    [1, "Ω"],
  ]);
}

/** Formats a frequency in Hz / kHz / MHz / GHz. */
export function formatFrequency(hz) {
  return formatWithPrefix(hz, [
    [1e9, "GHz"],
    [1e6, "MHz"],
    [1e3, "kHz"],
    [1, "Hz"],
  ]);
}

/** Formats a capacitance in F / mF / µF / nF / pF. */
export function formatCapacitance(farads) {
  return formatWithPrefix(farads, [
    [1, "F"],
    [1e-3, "mF"],
    [1e-6, "µF"],
    [1e-9, "nF"],
    [1e-12, "pF"],
  ]);
}

/** Formats an inductance in H / mH / µH / nH. */
export function formatInductance(henries) {
  return formatWithPrefix(henries, [
    [1, "H"],
    [1e-3, "mH"],
    [1e-6, "µH"],
    [1e-9, "nH"],
  ]);
}

/** Formats a time (seconds) in s / ms / µs / ns. */
export function formatTime(seconds) {
  return formatWithPrefix(seconds, [
    [1, "s"],
    [1e-3, "ms"],
    [1e-6, "µs"],
    [1e-9, "ns"],
  ]);
}

// Shared prefix formatter: `units` is a descending list of [scale, suffix].
// Picks the largest scale the value meets, prints up to 4 significant figures.
function formatWithPrefix(value, units) {
  if (!Number.isFinite(value) || value < 0) return "—";
  if (value === 0) return `0 ${units[units.length - 1][1]}`;
  for (const [scale, suffix] of units) {
    if (value >= scale) {
      return `${trim(toSignificant(value / scale, 4))} ${suffix}`;
    }
  }
  const [scale, suffix] = units[units.length - 1];
  return `${trim(toSignificant(value / scale, 4))} ${suffix}`;
}

/** Drops trailing zeros from a fixed-precision number for tidy display. */
function trim(n) {
  return Number(n.toFixed(6)).toString();
}

// The 24 base values of the E24 preferred-number series (IEC 60063). Used to
// snap a derived component to a value you can actually buy — the same series
// resistors, and most film capacitors, are sold in.
export const E24_BASE = [
  1.0, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2.0, 2.2, 2.4, 2.7, 3.0, 3.3, 3.6, 3.9,
  4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1,
];

// The 12 base values of the E12 series — the decade most through-hole
// hobbyist capacitors are actually stocked in.
export const E12_BASE = [
  1.0, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2,
];

/**
 * Finds the closest preferred-series value to an arbitrary positive value,
 * scanning the decade below, at, and above so a value like 9.6 snaps up to 10
 * (which lives in the next decade). `series` defaults to E24.
 */
export function nearestPreferred(value, series = E24_BASE) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error("Value must be a positive finite number.");
  }
  const exponent = Math.floor(Math.log10(value));
  let best = null;
  for (const exp of [exponent - 1, exponent, exponent + 1]) {
    const scale = 10 ** exp;
    for (const base of series) {
      const candidate = base * scale;
      const diff = Math.abs(candidate - value);
      if (best === null || diff < best.diff) best = { value: candidate, diff };
    }
  }
  // Clean the float so 2.2e-9 * scale doesn't render as 2.2000000000000003.
  return toSignificant(best.value, 6);
}

const FILTER_TYPES = new Set(["rc-lowpass", "rc-highpass", "rl-lowpass", "rl-highpass"]);

function isRc(type) {
  return type === "rc-lowpass" || type === "rc-highpass";
}

/**
 * Computes the -3 dB cutoff frequency (Hz), time constant (s), and angular
 * cutoff (rad/s) of a first-order filter from its components.
 *
 * For an RC filter pass { type, resistanceOhms, capacitanceFarads }.
 * For an RL filter pass { type, resistanceOhms, inductanceHenries }.
 */
export function cutoffFromComponents({
  type,
  resistanceOhms,
  capacitanceFarads,
  inductanceHenries,
}) {
  if (!FILTER_TYPES.has(type)) {
    throw new Error(`Unknown filter type: ${type}`);
  }
  if (!Number.isFinite(resistanceOhms) || resistanceOhms <= 0) {
    throw new Error("Resistance must be a positive number.");
  }

  let timeConstant;
  if (isRc(type)) {
    if (!Number.isFinite(capacitanceFarads) || capacitanceFarads <= 0) {
      throw new Error("Capacitance must be a positive number.");
    }
    timeConstant = resistanceOhms * capacitanceFarads;
  } else {
    if (!Number.isFinite(inductanceHenries) || inductanceHenries <= 0) {
      throw new Error("Inductance must be a positive number.");
    }
    timeConstant = inductanceHenries / resistanceOhms;
  }

  // Component values span many decades (pF to MΩ, nH to H), so round to
  // significant figures rather than decimal places — clean() would collapse a
  // capacitance-scale time constant like 1e-8 s to zero.
  const angularCutoff = toSignificant(1 / timeConstant, 9);
  const cutoffHz = toSignificant(angularCutoff / (2 * Math.PI), 9);
  return {
    cutoffHz,
    angularCutoffRadPerSec: angularCutoff,
    timeConstantSeconds: toSignificant(timeConstant, 9),
  };
}

/**
 * Design mode: given a target cutoff frequency and one known component,
 * solves for the other component, then snaps it to a buyable preferred value
 * and reports the cutoff that snapped value actually produces.
 *
 * `solveFor` is "capacitance" | "inductance" | "resistance". The component
 * you are NOT solving for must be supplied.
 */
export function designForCutoff({
  type,
  targetCutoffHz,
  solveFor,
  resistanceOhms,
  capacitanceFarads,
  inductanceHenries,
}) {
  if (!FILTER_TYPES.has(type)) {
    throw new Error(`Unknown filter type: ${type}`);
  }
  if (!Number.isFinite(targetCutoffHz) || targetCutoffHz <= 0) {
    throw new Error("Target cutoff frequency must be a positive number.");
  }
  const omega = 2 * Math.PI * targetCutoffHz;

  let exactValue;
  let snappedValue;
  let componentLabel;
  const resolved = {
    resistanceOhms,
    capacitanceFarads,
    inductanceHenries,
  };

  if (isRc(type)) {
    if (solveFor === "capacitance") {
      if (!Number.isFinite(resistanceOhms) || resistanceOhms <= 0) {
        throw new Error("Resistance must be a positive number to solve for capacitance.");
      }
      exactValue = 1 / (omega * resistanceOhms); // farads
      snappedValue = nearestPreferred(exactValue, E12_BASE);
      resolved.capacitanceFarads = snappedValue;
      componentLabel = "capacitance";
    } else if (solveFor === "resistance") {
      if (!Number.isFinite(capacitanceFarads) || capacitanceFarads <= 0) {
        throw new Error("Capacitance must be a positive number to solve for resistance.");
      }
      exactValue = 1 / (omega * capacitanceFarads); // ohms
      snappedValue = nearestPreferred(exactValue, E24_BASE);
      resolved.resistanceOhms = snappedValue;
      componentLabel = "resistance";
    } else {
      throw new Error("For an RC filter, solve for 'capacitance' or 'resistance'.");
    }
  } else {
    if (solveFor === "inductance") {
      if (!Number.isFinite(resistanceOhms) || resistanceOhms <= 0) {
        throw new Error("Resistance must be a positive number to solve for inductance.");
      }
      exactValue = resistanceOhms / omega; // henries
      snappedValue = nearestPreferred(exactValue, E12_BASE);
      resolved.inductanceHenries = snappedValue;
      componentLabel = "inductance";
    } else if (solveFor === "resistance") {
      if (!Number.isFinite(inductanceHenries) || inductanceHenries <= 0) {
        throw new Error("Inductance must be a positive number to solve for resistance.");
      }
      exactValue = omega * inductanceHenries; // ohms
      snappedValue = nearestPreferred(exactValue, E24_BASE);
      resolved.resistanceOhms = snappedValue;
      componentLabel = "resistance";
    } else {
      throw new Error("For an RL filter, solve for 'inductance' or 'resistance'.");
    }
  }

  const achieved = cutoffFromComponents({ type, ...resolved });

  return {
    componentLabel,
    exactValue: toSignificant(exactValue, 9),
    snappedValue,
    achievedCutoffHz: achieved.cutoffHz,
    achievedTimeConstantSeconds: achieved.timeConstantSeconds,
    // Signed percentage error of the snapped-value cutoff vs the target.
    cutoffErrorPercent: toSignificant(((achieved.cutoffHz - targetCutoffHz) / targetCutoffHz) * 100, 6),
    resolved,
  };
}

/**
 * Human-readable description of what a given filter type passes and blocks,
 * plus the standard first-order roll-off. Pure lookup, no arithmetic.
 */
export function describeFilter(type) {
  switch (type) {
    case "rc-lowpass":
      return "Passes frequencies below the cutoff and attenuates those above it at −20 dB/decade (−6 dB/octave). Output taken across the capacitor.";
    case "rc-highpass":
      return "Passes frequencies above the cutoff and attenuates those below it at −20 dB/decade (−6 dB/octave). Output taken across the resistor.";
    case "rl-lowpass":
      return "Passes frequencies below the cutoff and attenuates those above it at −20 dB/decade (−6 dB/octave). Output taken across the resistor.";
    case "rl-highpass":
      return "Passes frequencies above the cutoff and attenuates those below it at −20 dB/decade (−6 dB/octave). Output taken across the inductor.";
    default:
      throw new Error(`Unknown filter type: ${type}`);
  }
}

rc-filter-calculator/share.mjs.text:
// Shareable filter-design link. A student checking a homework answer with a
// classmate, or an engineer sending a colleague the exact component values
// and unit scaling they used, needs the recipient to see the same filter --
// the topology, which mode was active (read a cutoff from components, or
// design a component for a target cutoff), every value, and which unit each
// one was entered in -- not just a cutoff frequency a screenshot would show.
// Retyping eleven fields across two modes and four component families is how
// that check never happens, and a silently dropped unit selector is how the
// recipient reads a value in the wrong scale (10 kΩ misread as 10 Ω is a
// thousand-fold error, not a rounding one). The transform is pure: no DOM,
// no storage, no network, and everything after the # never reaches a server.
//
// Every field here is either a plain non-negative number (the seven typed
// values: r, c, l, target, dr, dc, dl) or a fixed enum this page's own
// <select>/radio options offer (the filter type, the mode, each unit
// multiplier, and which component design mode solves for) -- there are no
// checkboxes and no visitor-grown rows, so the plain "one query param per
// field" pattern from the fleet's bid calculators applies directly, with
// enums validated the same way `screened-porch-bid-calculator`'s ENUM_FIELDS
// are, against this page's own option values rather than a value guessed at
// here.
//
// `solve-for` is the one enum whose *offered* options change with the
// filter family (capacitance/inductance vs resistance) -- see
// `rebuildSolveOptions()` in index.html. Rather than re-derive that
// dependency here (and risk it drifting from the page's own logic), the
// full universal set the page can ever assign is accepted; index.html
// re-applies it only after rebuilding the option list for the restored
// type, so a value that would not apply to that type is simply not one of
// the options `.value =` can select, and the page's own default stands.

export const NUMBER_FIELD_IDS = ['r', 'c', 'l', 'target', 'dr', 'dc', 'dl'];

export const BOOLEAN_FIELD_IDS = [];

export const ENUM_FIELDS = Object.freeze({
  type: ['rc-lowpass', 'rc-highpass', 'rl-lowpass', 'rl-highpass'],
  mode: ['cutoff', 'design'],
  'r-unit': ['1', '1e3', '1e6'],
  'c-unit': ['1e-12', '1e-9', '1e-6', '1e-3'],
  'l-unit': ['1e-9', '1e-6', '1e-3', '1'],
  'dr-unit': ['1', '1e3', '1e6'],
  'dc-unit': ['1e-12', '1e-9', '1e-6', '1e-3'],
  'dl-unit': ['1e-9', '1e-6', '1e-3', '1'],
  'target-unit': ['1', '1e3', '1e6'],
  'solve-for': ['capacitance', 'inductance', 'resistance'],
});

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

function usableEnum(value, allowed) {
  return allowed.includes(value) ? value : null;
}

export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of NUMBER_FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const [id, allowed] of Object.entries(ENUM_FIELDS)) {
    const value = usableEnum(inputs?.[id], allowed);
    if (value !== null) params.set(id, value);
  }
  return params.toString();
}

export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const inputs = {};
  for (const id of NUMBER_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  for (const [id, allowed] of Object.entries(ENUM_FIELDS)) {
    if (!params.has(id)) continue;
    const value = usableEnum(params.get(id), allowed);
    if (value !== null) inputs[id] = value;
  }
  return inputs;
}

rc-filter-calculator/usage.mjs.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No IDs, no IPs, no content — just an event
// name and a day, kept in this browser's own localStorage. Nothing is sent
// anywhere; there is no server for it to go to. Off-switchable, and honors
// Do Not Track / Global Privacy Control automatically.

const STORAGE_KEY = "rc-filter-calculator:usage-events";
const OPT_OUT_KEY = "rc-filter-calculator:usage-opt-out";

function hasStorage() {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function honorsBrowserSignal() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function isUsageCountingEnabled() {
  if (!hasStorage()) return false;
  if (honorsBrowserSignal()) return false;
  try {
    return localStorage.getItem(OPT_OUT_KEY) !== "1";
  } catch {
    return false;
  }
}

export function setUsageCountingEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch {
    // storage unavailable (private mode, quota) — nothing to do
  }
}

/** Records that `eventName` happened today. Aggregate count only; no payload beyond the event name and the day. */
export function recordEvent(eventName) {
  if (!isUsageCountingEnabled()) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const raw = localStorage.getItem(STORAGE_KEY);
    const events = raw ? JSON.parse(raw) : {};
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch {
    // storage unavailable — counting is best-effort only
  }
}

// How long an input must sit unchanged before the interaction counts as one
// event. Long enough to span ordinary typing (including a pause to look at
// the result), short enough that a user who types and immediately leaves is
// still counted.
const SETTLE_MS = 800;

const pendingTimers = new Map();

/**
 * Records `eventName` once the user has stopped changing inputs, rather than
 * once per keystroke.
 *
 * These tools recompute on every `input` event, which is right for the
 * result but wrong for the counter: calling recordEvent() from that handler
 * counted keystrokes, so typing "220" into one field recorded three
 * calculations and a five-field form could record a dozen. That made the
 * only signal these tools produce -- "did anyone actually use this" --
 * unreadable, and portfolio/usage/ is what decides what gets built next.
 *
 * Repeated calls for the same event name collapse into one, so a burst of
 * typing yields a single count once it settles. Different event names are
 * tracked independently, so two calculators on one page each keep their own.
 */
export function recordEventSettled(eventName, delayMs = SETTLE_MS) {
  const existing = pendingTimers.get(eventName);
  if (existing !== undefined) clearTimeout(existing);
  const timer = setTimeout(() => {
    pendingTimers.delete(eventName);
    recordEvent(eventName);
  }, delayMs);
  // Under Node (the test runner) a pending timer keeps the process alive;
  // browsers have no unref, hence the guard rather than a bare call.
  if (typeof timer === "object" && typeof timer?.unref === "function") timer.unref();
  pendingTimers.set(eventName, timer);
}

/** Records any settled-but-not-yet-written events immediately. Exists so tests need not wait on wall-clock time. */
export function flushSettledEvents() {
  for (const [eventName, timer] of pendingTimers) {
    clearTimeout(timer);
    recordEvent(eventName);
  }
  pendingTimers.clear();
}

/** Discards pending settled events without recording them. Used by tests to isolate cases. */
export function cancelSettledEvents() {
  for (const timer of pendingTimers.values()) clearTimeout(timer);
  pendingTimers.clear();
}

/** Returns the raw local event counts, for the user's own inspection. */
export function readLocalUsage() {
  if (!hasStorage()) return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

rc-time-calculator/calc.mjs.text:
// Pure RC charge/discharge timing math. Inputs are SI units.

export const E24_BASE = [1, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2, 2.2, 2.4, 2.7, 3, 3.3, 3.6, 3.9, 4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1];
export const E12_BASE = [1, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2];

function positive(value, label) {
  if (!Number.isFinite(value) || value <= 0) throw new Error(`${label} must be a positive number.`);
}

export function toSignificant(value, sig = 4) {
  if (!Number.isFinite(value) || value === 0) return value;
  const exponent = Math.floor(Math.log10(Math.abs(value)));
  return Math.round(value * 10 ** (sig - 1 - exponent)) / 10 ** (sig - 1 - exponent);
}

export function nearestPreferred(value, series = E24_BASE) {
  positive(value, "Value");
  const exponent = Math.floor(Math.log10(value));
  let best;
  for (const exp of [exponent - 1, exponent, exponent + 1]) {
    for (const base of series) {
      const candidate = base * 10 ** exp;
      const diff = Math.abs(candidate - value);
      if (!best || diff < best.diff) best = { value: candidate, diff };
    }
  }
  return toSignificant(best.value, 6);
}

export function formatWithPrefix(value, units) {
  if (!Number.isFinite(value) || value < 0) return "-";
  if (value === 0) return `0 ${units[units.length - 1][1]}`;
  for (const [scale, suffix] of units) {
    if (value >= scale) return `${toSignificant(value / scale, 4)} ${suffix}`;
  }
  const [scale, suffix] = units[units.length - 1];
  return `${toSignificant(value / scale, 4)} ${suffix}`;
}

export const formatResistance = v => formatWithPrefix(v, [[1e6, "MΩ"], [1e3, "kΩ"], [1, "Ω"]]);
export const formatCapacitance = v => formatWithPrefix(v, [[1, "F"], [1e-3, "mF"], [1e-6, "µF"], [1e-9, "nF"], [1e-12, "pF"]]);
export const formatTime = v => formatWithPrefix(v, [[1, "s"], [1e-3, "ms"], [1e-6, "µs"], [1e-9, "ns"]]);

// `mode` is charge (from 0 toward supply) or discharge (from initial voltage toward 0).
export function timeFromComponents({ mode, resistanceOhms, capacitanceFarads, supplyVolts, initialVolts = supplyVolts, thresholdVolts }) {
  if (!new Set(["charge", "discharge"]).has(mode)) throw new Error("Mode must be charge or discharge.");
  positive(resistanceOhms, "Resistance");
  positive(capacitanceFarads, "Capacitance");
  positive(supplyVolts, "Supply voltage");
  positive(thresholdVolts, "Threshold voltage");
  if (mode === "charge") {
    if (thresholdVolts >= supplyVolts) throw new Error("Charge threshold must be below the supply voltage.");
    if (thresholdVolts <= 0) throw new Error("Charge threshold must be above zero.");
  } else {
    positive(initialVolts, "Initial voltage");
    if (thresholdVolts >= initialVolts) throw new Error("Discharge threshold must be below the initial voltage.");
  }
  const ratio = mode === "charge" ? 1 - thresholdVolts / supplyVolts : thresholdVolts / initialVolts;
  const timeConstantSeconds = resistanceOhms * capacitanceFarads;
  return { timeSeconds: toSignificant(-timeConstantSeconds * Math.log(ratio), 9), timeConstantSeconds: toSignificant(timeConstantSeconds, 9) };
}

export function designForTime({ mode, targetTimeSeconds, solveFor, resistanceOhms, capacitanceFarads, supplyVolts, initialVolts = supplyVolts, thresholdVolts }) {
  positive(targetTimeSeconds, "Target time");
  const probe = timeFromComponents({ mode, resistanceOhms: resistanceOhms || 1, capacitanceFarads: capacitanceFarads || 1, supplyVolts, initialVolts, thresholdVolts });
  const factor = probe.timeSeconds / ((resistanceOhms || 1) * (capacitanceFarads || 1));
  let exactValue;
  let componentLabel;
  if (solveFor === "resistance") {
    positive(capacitanceFarads, "Capacitance");
    exactValue = targetTimeSeconds / (capacitanceFarads * factor);
    componentLabel = "resistance";
  } else if (solveFor === "capacitance") {
    positive(resistanceOhms, "Resistance");
    exactValue = targetTimeSeconds / (resistanceOhms * factor);
    componentLabel = "capacitance";
  } else throw new Error("Solve for must be resistance or capacitance.");
  const snappedValue = nearestPreferred(exactValue, componentLabel === "capacitance" ? E12_BASE : E24_BASE);
  const result = componentLabel === "resistance" ? { resistanceOhms: snappedValue, capacitanceFarads } : { resistanceOhms, capacitanceFarads: snappedValue };
  const achieved = timeFromComponents({ mode, ...result, supplyVolts, initialVolts, thresholdVolts });
  return { componentLabel, exactValue, snappedValue, achievedTimeSeconds: achieved.timeSeconds, errorPercent: (achieved.timeSeconds / targetTimeSeconds - 1) * 100 };
}

/**
 * Capacitor voltage after a given time. The inverse of `timeFromComponents`:
 * that answers "how long to this threshold", this answers "what voltage
 * after this delay" — the question when you already have the part values
 * and a clock edge, not a target trip point.
 */
export function voltageAtTime({ mode, resistanceOhms, capacitanceFarads, supplyVolts, initialVolts = supplyVolts, timeSeconds }) {
  if (!new Set(["charge", "discharge"]).has(mode)) throw new Error("Mode must be charge or discharge.");
  positive(resistanceOhms, "Resistance");
  positive(capacitanceFarads, "Capacitance");
  positive(supplyVolts, "Supply voltage");
  if (!Number.isFinite(timeSeconds) || timeSeconds < 0) throw new Error("Time must not be negative.");
  const timeConstantSeconds = resistanceOhms * capacitanceFarads;
  const ratio = Math.exp(-timeSeconds / timeConstantSeconds);
  if (mode === "charge") {
    const volts = supplyVolts * (1 - ratio);
    return {
      volts: toSignificant(volts, 9),
      fractionOfSupply: toSignificant(volts / supplyVolts, 9),
      timeConstantSeconds: toSignificant(timeConstantSeconds, 9),
    };
  }
  positive(initialVolts, "Initial voltage");
  const volts = initialVolts * ratio;
  return {
    volts: toSignificant(volts, 9),
    fractionOfInitial: toSignificant(volts / initialVolts, 9),
    timeConstantSeconds: toSignificant(timeConstantSeconds, 9),
  };
}

rc-time-calculator/settling.mjs.text:
// Pure logic for "how long until a capacitor is basically fully charged?" —
// the question that comes before anyone has picked a specific trip-point
// voltage. The parent page's "Timing" section already answers "how long to
// reach this threshold", but that requires a threshold, and the question
// people actually type into a search box does not have one yet.
//
// No DOM, no network, no state. Imports voltageAtTime and formatTime from
// calc.mjs rather than restating the exponential-charging formula — see
// CLAUDE.md on the two occasions copying a rule out of a module instead of
// importing it has cost live product.

import { voltageAtTime, formatTime, toSignificant } from "./calc.mjs";

function positive(value, label) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${label} must be a positive number.`);
  }
}

// Common multiples of the time constant people actually reach for when
// asking "is it done yet". None of these is "the" right answer — an
// exponential charge has no finish line — so the table states the exact
// percentage each one reaches rather than asserting one of them is correct.
export const SETTLING_MULTIPLES = [1, 2, 3, 4, 5, 6, 7, 10];

/**
 * The percent of the supply reached after each of SETTLING_MULTIPLES time
 * constants, plus the real elapsed time for this circuit's own R and C.
 * Every figure comes from voltageAtTime — the same function the parent
 * page's "voltage after a delay" section uses — evaluated at t = n * RC, so
 * this table cannot drift out of step with the calculator it extends.
 */
export function chargeSettlingTable({ resistanceOhms, capacitanceFarads, supplyVolts }) {
  positive(resistanceOhms, "Resistance");
  positive(capacitanceFarads, "Capacitance");
  positive(supplyVolts, "Supply voltage");
  const tau = resistanceOhms * capacitanceFarads;
  return SETTLING_MULTIPLES.map((multiple) => {
    const timeSeconds = multiple * tau;
    const { volts, fractionOfSupply } = voltageAtTime({
      mode: "charge",
      resistanceOhms,
      capacitanceFarads,
      supplyVolts,
      timeSeconds,
    });
    return {
      multiple,
      timeSeconds,
      formattedTime: formatTime(timeSeconds),
      volts,
      percentOfSupply: toSignificant(fractionOfSupply * 100, 6),
    };
  });
}

/**
 * Inverts the charging equation to answer "how long until I'm at P% of the
 * supply" for any P a person picks, not only the fixed multiples in the
 * table above. Derived directly from V(t) = Vs * (1 - e^(-t/RC)):
 *
 *   P/100 = 1 - e^(-t/RC)   =>   t = -RC * ln(1 - P/100)
 *
 * P must be strictly below 100. An RC charge approaches the supply
 * asymptotically and never mathematically reaches it — the remaining gap
 * only ever halves and halves again — so "100%" has no finite time and is
 * refused rather than silently returning Infinity.
 */
export function timeToReachPercent({ resistanceOhms, capacitanceFarads, percentOfSupply }) {
  positive(resistanceOhms, "Resistance");
  positive(capacitanceFarads, "Capacitance");
  if (!Number.isFinite(percentOfSupply) || percentOfSupply <= 0 || percentOfSupply >= 100) {
    throw new Error(
      "Target percent must be greater than 0 and less than 100 — an RC charge " +
        "never mathematically reaches 100% of the supply, only closer and closer to it.",
    );
  }
  const tau = resistanceOhms * capacitanceFarads;
  const remainingFraction = 1 - percentOfSupply / 100;
  const timeSeconds = -tau * Math.log(remainingFraction);
  return {
    timeSeconds: toSignificant(timeSeconds, 9),
    formattedTime: formatTime(timeSeconds),
    timeConstants: toSignificant(timeSeconds / tau, 6),
  };
}

